linked as (
  update public.listings l set parent_id = p.main, location_label = coalesce(nullif(l.location_label, ''), p.label), updated_at = now()
  from plan p
  where l.id = p.id and l.parent_id is null and l.status = 'approved'
    and exists (select 1 from public.listings m where m.id = p.main and m.parent_id is null and m.status = 'approved')
  returning l.id, p.main, l.location_label)
insert into public.ve_listing_edits (listing_id, member_id, field, old_value, new_value, meta)
select id, null, 'parent_id', null, to_jsonb(main::text), jsonb_build_object('by', 'logan', 'where', 'chain_locations', 'label', location_label)
from linked;
